# -*- coding: utf-8 -*-
"""矛盾驱动补盲 · 批次C17（v15 新域 7 簇+直答：独居青年/培训贷/高考复读/隔代育儿/旧手机回收/社区团购/儿童零花钱）
注：高铁餐饮簇 v15 基线已 6/6 全绿（「高铁盒饭」等长短语长度决胜公共文明簇），本批不补。
"""
def patch(path):
    src = open(path, encoding="utf-8").read()
    anchor_c = '    "注意机制": ["注意机制", "选择性注意", "分散注意", "什么是注意机制"],'
    new_c = '''    "独居青年": ["独居", "独居生活", "独居久了", "独居怎么", "一个人住"],
    "培训贷": ["培训贷", "培训", "先贷款", "想学技能", "培训机构",
              "判断培训"],
    "高考复读": ["复读", "再拼一年", "不甘心", "复读一年", "复读还是"],
    "隔代育儿": ["老人带娃", "插手带娃", "老人总要插手", "隔代", "带孙",
              "老人帮忙带", "老人和父母怎么分工"],
    "旧手机回收": ["旧手机", "手机还能用", "换什么换", "旧手机卖", "手机回收",
              "换手机", "手机怎么处理"],
    "社区团购": ["社区团购", "团购", "这么便宜", "便宜不好吗", "菜市场",
              "买菜", "团购怎么选"],
    "儿童零花钱": ["零花钱", "孩子乱花钱", "乱花钱怎么办", "给零花钱", "偷拿",
              "教孩子管钱", "管钱"],'''
    assert anchor_c in src, "cluster anchor missing"
    src = src.replace(anchor_c, new_c + "\n    " + anchor_c, 1)

    anchor_d = '    "注意机制": "注意机制是认知资源的选择性分配——选择性注意（聚焦）/分散注意（多任务）/持续注意；对应CSPMN只匹配激活条件空间",'
    new_d = '''    "独居青年": "越来越多人独居、独居是自由还是孤独，是『独立空间』vs『社会连接』的矛盾——独居给人自由（空间自己做主/节奏自己定/不被干涉），但独居也放大孤独（下班回家没人说话/生病没人照顾/情绪没人分担），一个人住的自由和一个人扛的孤独是同一枚硬币的两面。真相：①为什么越来越多人独居——结构变化：结婚推迟（初婚年龄逼近30，独居期变长）、工作流动（异地打拼，离开原生家庭）、生活方式（一个人过得很自在：外卖/独居公寓/线上社交填补了以前必须合群的部分）——独居是城市化的副产品（大城市年轻人独居比例超50%），不是矫情是社会变了；②独居是自由还是孤独——都是：自由是真的（门一关世界是我的：想几点睡几点睡/想裸奔就裸奔（开玩笑）/不用迁就任何人），孤独也是真的（独居者的孤独感显著高于合居者：尤其节假日/生病/深夜）——自由和孤独不矛盾（自由是有代价的，孤独就是自由的租金），关键是你能不能handle（有人享受独居（内向者充电），有人被孤独吞噬（外向者需要人群））；③独居自由有错吗——没错：独居是成年人的权利（自己选择的生活方式，不违法不伤害别人），『独居=不合群=有问题』是偏见（独居者有自己的社交圈，只是不住一起），别用『孤独终老』恐吓独居者（独居≠孤独终老，独居可以很幸福，合居也可以很孤独）；④独居久了会不会废掉——会废的是『被动独居』（没朋友/不社交/生活混乱），不会废的是『主动独居』（有社交/有规律/有追求）——关键指标：独居期间有没有保持社会连接（朋友/家人/同事）和生活秩序（作息/饮食/运动），独居+自律=自由，独居+颓废=废掉。怎么过得好：①连接——固定社交（每周约朋友/参加兴趣小组/养宠物（宠物是独居的解药））、和家里保持联系（每周视频，独居不是失联）、发展线上线下的圈子（独居最怕的是没圈子）；②秩序——规律作息（独居没人管，更要自己管：熬夜是独居最大杀手）、做饭（外卖吃久了身体垮，一周做几次饭）、运动（独居+久坐+外卖=亚健康套餐）；③安全——独居安全网：锁好门/邻里熟识（紧急情况有人帮）/紧急联系人（手机存好/告诉朋友）、独居应急（生病预案：常用药/朋友备用钥匙）；④心态——独居是人生阶段不是最终形态（享受当下的自由，也保持开放：遇到合适的人/合适的生活方式可以改变），『一个人也能过得好』是能力不是认命。核心：独居的自由要配独居的自律——有连接、有秩序、有安全，一个人住也能把日子过成诗，否则就是把孤独过成灾难",
    "培训贷": "培训先贷款、培训贷是馅饼还是陷阱，是『学技能的渴望』vs『机构的套路』的矛盾——想学技能（编程/剪辑/配音/考证）没学费，机构说『先贷款，学完就业再还』（听着美好：0元入学/学成上岗/月薪过万），实际是贷款合同签了（利息高/退费难/就业承诺是假的），『培训贷』让想上进的年轻人背上债务。真相：①为什么培训总是先贷款——商业模式：培训机构的利润来源是『学费』，『0元入学』是获客话术（把学费压力转移给贷款公司，机构立刻收到全款，学员慢慢还贷）——机构赚的是『贷款流水』不是『教学质量』（学员学没学会/就没就业，钱已经到手），『先贷款』是机构的现金流设计，不是为你着想；②培训贷是馅饼还是陷阱——多数是陷阱：馅饼的（正规机构+真实培训+贷款正常还款）极少，陷阱的（利息高（分期手续费折算年化10-20%）/霸王条款（退费难，贷款还不退）/'保就业'是假的（就业合同不写进贷款协议））是主流——『学技能没钱』是真实需求，但『用贷款解决』是被利用（培训机构盯上的是你的贷款额度）；③想学技能没钱贷款有错吗——贷款本身没错（教育投资可以贷款：正规助学贷款/银行消费贷），错的是『被动贷款』（机构诱导/隐瞒条款/把贷款说成免费）——想贷款自己贷（银行正规渠道，利息透明），别通过机构贷（机构经手的贷款，你根本不知道签了什么）；④培训机构也是生意赚钱有错吗——没错：培训是生意（赚钱天经地义），错的是『骗钱』（虚假宣传（保就业/月入过万）/诱导贷款（隐瞒利息）/售后退费难）——生意的底线是诚实（赚学费可以，别拿贷款套学员），好机构靠口碑赚钱，坏机构靠套路赚钱。怎么判断值不值：①先查机构——资质（办学许可证/经营范围）、口碑（黑猫投诉/知乎/贴吧搜『XX培训 骗局』）、办学年限（3年以上的活下来的一般还行）、退费政策（合同里写明，7天无理由退费是良心）；②警惕红线——『先贷款后学习』『保就业月薪过万』『名额有限今天报名优惠』（饥饿营销）『学不会免费重修』（重修不退款）——中2条以上直接跑；③试听体验——免费试听课（真实课程质量：老师讲得好不好/内容实不实用）、问已毕业学员（就业情况/真实薪资，别信机构给的案例）；④替代方案——自学（B站/慕课/书，很多技能免费学）、付费系统课（几千块的网课，不用贷款）、政府补贴培训（人社局/工会的免费技能培训）——『花大钱培训』不是唯一路，别被『不培训就没出路』吓住。核心：培训贷的本质是『用你的未来还机构的学费』——想学技能是好事，但先想清楚：这个培训值不值？这个贷款能不能不贷？真正值钱的技能，不需要用贷款来证明",
    "高考复读": "越来越多人复读、复读一年值吗，是『不甘心』vs『机会成本』的矛盾——高考没考好（差几分/发挥失常/滑档），复读是再来一次的机会（一年时间换更好的大学），但复读是赌（不确定能提分/心理压力大/一年青春）——复读的诱惑（万一逆袭）和风险（万一更差）让每个落榜生纠结。真相：①为什么越来越多人复读——三股力量：不甘心（差几分/发挥失常，『我能更好』）、就业压力传导（学历贬值，本科不好就考不上研究生/进不了好单位，复读一年冲好大学）、机构推波（复读学校/机构宣传『逆袭案例』，制造『不复读就亏了』的焦虑）——复读热是应试竞争的延伸（卷本科，卷不到就重来）；②复读一年值吗——看三件事：潜力（这次是发挥失常（平时650考了580）→复读提分空间大；正常水平（平时500考了495）→复读提分有限（大概率原地踏步））、心态（抗压能力强（复读是高压：再来一年+同学都上大学了）vs 心态脆（复读一年可能更崩））、目标（差一点够得着（冲211差10分）→值；差太远（二本冲清北）→不值）——复读是投资，值不值看『预期回报』；③不甘心再拼一年有错吗——没错：不甘心是正常的（努力了没结果，想再试一次是勇气），『再拼一年』是个人选择（自己的青春自己负责）——但『不甘心』要区分：是『我还能更好』（潜力）还是『我咽不下这口气』（情绪）——情绪驱动复读（赌气）容易二次失败，潜力驱动复读（有依据）才值得；④复读是机会还是逃避——都是：机会（第二次机会，有人复读逆袭清北）和逃避（逃避就业/逃避现实/不敢进入人生下一阶段）并存——判断：复读是为了『更好的目标』（机会）还是『不想面对结果』（逃避）——如果复读期间你能保持学习状态（不是换个地方玩一年），是机会；如果是『不想上班/不想长大』，是逃避。怎么选不后悔：①冷静评估——拿成绩单说话：算清这次和平时水平的差距（发挥失常→复读有空间）、问老师（班主任最了解你：潜力/心态）、做决定前想『最坏结果』（复读一年还这样，能接受吗）；②复读条件——学校（找正规复读学校/回母校，别去野鸡复读班）、资金（复读费用1-5万，家里支持吗）、心态（能接受『同学都走了我还在』的孤独感）；③复读策略——不复读的路也很好（二本也能考研/专升本/就业，人生不是一考定终身），复读的全力冲（目标明确/方法改进/心态管理）；④决定后——选了复读就全力以赴（别再纠结『值不值』，纠结是复读最大敌人），选了走就安心走（不复读不是认输，是选择另一条路）。核心：复读是一年的豪赌——赌的不是运气是潜力，评估清楚（差距/心态/目标）再下注，赌赢了是逆袭，赌输了也认（青春不是只有一场考试）",
    "隔代育儿": "老人总插手带娃、老人带娃有什么问题，是『老人的爱』vs『父母的教育理念』的矛盾——老人帮忙带娃（真心/经验/免费，解放了双职工父母），但老人的带法（宠溺/老观念/按自己的经验）和父母的教育理念（科学育儿/立规矩）冲突：『我们当年都这么带大的』vs『现在不一样了』，隔代育儿成了家庭吵架的头号导火索。真相：①为什么老人总要插手带娃——三重心理：爱（孙子是心头肉，想参与孩子的成长）、价值感（退休后带孙=还有用/被需要）、习惯（自己养大过孩子，觉得有经验有资格）——『插手』不是老人想控制你，是老人表达爱的方式（他们那个年代，帮带孙就是最大的支持）；②老人带娃有什么问题——现实问题：观念代差（把尿/嚼喂/捂热/发烧捂汗——老一辈的经验有些是错的）、宠溺（隔代亲：孙子要什么给什么，立不起规矩）、体力（老人带娃累，容易烦躁/看不住）、界限（老人觉得『我带的孙子我做主』）——问题不是老人坏，是『用旧方法带新孩子』；③老人帮忙带还挑三拣四——这话要两面看：老人帮忙是情分（不帮是本分，帮了要感恩），但『帮忙』不等于『说了算』（育儿的主导权在父母——老人是助手不是主管）——『挑三拣四』（嫌老人带得不好）之前先想：你带过吗？（全职带娃一周试试，就知道老人多辛苦），嫌弃要具体（指出问题+给出替代方案，不是全盘否定）；④老人带娃省钱又省心不好吗——好处是真的（省钱（保姆一个月几千）/省心（亲奶奶比保姆放心）），代价也是真的（教育理念冲突/孩子被惯坏/夫妻和老人的关系紧张）——『省钱省心』是表面，背后是『用关系换钱』（省了保姆钱，费了家庭和气）——关键是管理好『带』和『教』的分工。怎么不吵架：①分工明确——老人管『生活』（吃穿/接送/陪伴）父母管『教育』（习惯/规矩/学习）——提前说好（『妈，您负责她吃好睡好，规矩的事我们来说』），界限清晰减少摩擦；②原则问题不让步——安全/健康（不能把尿/不能乱喂药）底线不能妥协（老人也爱孩子，用科学证据说话：『医生说了…』），非原则问题随老人（穿多穿少/吃不吃零食，别事事纠正，老人也要面子）；③感恩表达——承认老人的付出（『妈您辛苦了』比指出问题重要）、物质回报（给钱/买礼物/带老人体检）、让老人有成就感（夸她带得好）——老人被尊重了，才听得进你的意见；④夫妻同心——教育分歧夫妻先统一（别一个说一个拆台）、老公/老婆是沟通桥梁（各自搞定自己的父母，别让配偶直面公婆/岳父母）——隔代育儿的矛盾，一半是育儿问题，一半是家庭权力问题。核心：老人带娃是帮忙不是接管——生活归老人、教育归父母、感恩在前、沟通在后，两代人各退一步，孩子才能在有爱又守规矩的环境里长大",
    "旧手机回收": "旧手机怎么处理、回收安全吗，是『换新的欲望』vs『旧物的价值/隐私』的矛盾——手机更新快（两年一换是常态），换下来的旧手机（还能用/有数据/值点钱）怎么处理：留着吃灰（浪费）、卖二手（怕隐私泄露）、回收（怕数据被恢复）——旧手机里存着你的全部数字人生（照片/聊天/支付/账号），处理不当=隐私裸奔。真相：①旧手机怎么处理——三条路：留用（备用机/给孩子/当遥控器——能用就别浪费）、二手变现（卖闲鱼/回收平台——回血几百到几千）、正规回收（官方以旧换新/回收平台——省心）——最浪费的是『抽屉吃灰』（占地方还贬值（电子产品一年贬值一半））；②旧手机回收安全吗——看你怎么处理：数据删干净+恢复出厂=基本安全（专业数据恢复也难找回）、直接卖/直接扔=危险（删掉的文件能恢复，恢复出厂也可能被恢复（如果没加密/没覆盖））——安全公式：备份→退出账号→加密清除（iOS『抹掉所有内容和设置』/安卓『恢复出厂设置』+勾选清除所有数据）→再卖——两步操作（退出账号+恢复出厂）就能挡住99%的泄露；③手机还能用换什么换——这个问题问得好：手机还能用（不卡/不坏）确实不用换（换机是消费主义（新款发布/广告种草制造『旧机不行了』的错觉）），该换的时候（电池撑不住/卡到影响使用/坏了修不值）再换——『能用』和『好用』是两回事（能打电话的老年机和流畅打游戏的旗舰机，需求不同），换不换看你的需求（不是看新款发布）；④旧手机卖钱有错吗——没错：旧物变现是正当的（手机是你的，卖不卖自由），『卖旧手机』还环保（电子垃圾是污染大户，回收利用减少资源浪费）——但卖之前做好三件事（退出账号（不然对方能登你的微信/支付）/恢复出厂（清数据）/删除SD卡（很多人忘删内存卡）），卖得安心才卖得对。怎么处理最划算：①及时处理——换新机当天处理旧机（越晚越贬值（一年降一半）），不想卖就明确用途（备用/给孩子/捐赠），别让旧机在抽屉里悄悄过期；②渠道——官方以旧换新（省心/估价低）、闲鱼/转转（价高/自己卖麻烦）、回收平台（估价/顺丰上门，选大平台）——比价（同一台手机不同渠道差几百很正常）；③隐私清道夫——备份（照片/通讯录/微信记录先备份）→退出所有账号（微信/支付宝/各APP，不退出账号=把钥匙交给别人）→恢复出厂设置（加密清除，别只删文件）→检查（开机确认是『新机状态』）——这套流程做完，手机可以放心卖；④心态——手机是工具不是藏品（用旧了处理掉是正常循环，『舍不得』留到不能用=浪费空间也浪费价值），换机卖旧是精明不是浪费（你会算这笔账，说明你驾驭了消费而不是被消费驾驭）。核心：旧手机是沉睡的资产也是行走的隐私——及时处理+安全清除，让旧机发挥余热，让数据安全落地，两全其美",
    "社区团购": "社区团购这么便宜、团购抢了菜市场的生意，是『低价便利』vs『品质/小摊贩生存』的矛盾——社区团购（次日达/自提点/补贴低价）让买菜便宜方便（比菜市场便宜20-30%），但它的便宜是烧钱补贴换来的（平台用资本换市场），便宜背后：菜品质可能打折扣（隔夜菜/不新鲜）、菜市场小摊贩被冲击（生意被抢，卖菜大叔大妈失业）——你省的钱，是别人丢的饭碗。真相：①为什么社区团购这么便宜——三重原因：补贴烧钱（平台为了抢市场，用资本补贴（一份菜亏几毛）——『便宜』是暂时的（补贴结束就涨价，参考外卖/网约车：烧钱期便宜，垄断后涨价））、规模效应（集中采购/中央仓/减少中间商——这个是真便宜（供应链优化））、品质让步（隔夜/不新鲜/规格不统一——部分便宜来自品质打折）；②社区团购靠谱吗——看品类看平台：靠谱的（大平台+标品（米面油/日用品）——规格统一/价格透明）、不靠谱的（生鲜（菜/肉/水果）——看不见摸不着，到手不新鲜/以次充好（『团长』也有挑拣空间））——团购适合买『标准品』（日用品/米面），生鲜还是眼见为实（菜市场/超市能挑）；③便宜不好吗——便宜好，但要看便宜的来源：供应链优化（真便宜，好）+ 补贴（假便宜，会涨）+ 品质让步（亏品质的便宜）——『便宜』本身没错（谁不想省钱），错的是『为了便宜牺牲品质/让卖菜的人失业』——聪明的消费是『该省省该花花』（团购买日用品，生鲜买新鲜的）；④团购抢了菜市场的生意——现实冲击：社区团购确实抢了小摊贩的生意（同样的菜，平台更便宜/更方便，顾客流失）、但菜市场有团购替代不了的（新鲜（现挑现买）/人情（和摊贩熟，帮你留好菜）/烟火气（逛菜市场是生活））——菜市场不会被消灭（会转型：卖特色/卖服务/卖体验），但小摊贩的生存确实需要关注（平台别把卖菜的路堵死，政府监管别让巨头垄断菜篮子）。怎么选：①组合买菜——标品（米面油/纸巾）团购（便宜方便）、生鲜（菜/肉/鱼）菜市场/超市（新鲜能挑）、应急（临时缺什么）楼下便利店——每个渠道用它的长处；②看平台——大平台（美团优选/多多买菜/淘菜菜）有保障（售后/退换），小团长（私人群）谨慎（没有平台兜底）；③自提检查——取货时当场验（菜不新鲜当场退/换，别拿回家才发现）、生鲜尽快吃（团购的菜是前一天到货的，别囤）；④心态——支持菜市场（偶尔去逛逛，让摊贩活着（他们也是城市的一部分））、理性看待团购（它改变了买菜方式，但别让它垄断了你的餐桌）。核心：社区团购是渠道不是全部——便宜买标品、新鲜去市场，让平台和菜市场共存（都别垄断），你的菜篮子才既便宜又新鲜",
    "儿童零花钱": "该不该给孩子零花钱、孩子乱花钱怎么办，是『金钱教育』vs『惯坏担心』的矛盾——给零花钱是财商教育的第一步（孩子要学花钱：预算/取舍/存钱，零花钱是最好的练习场），但家长怕（给了乱花/惯坏/养成花钱大手大脚的毛病）——不给（孩子没机会学花钱，大了不会管钱/偷拿）vs 给（怕学坏）——零花钱给不给不是问题，怎么给才是。真相：①该不该给孩子零花钱——该：零花钱是财商教育的必需品（孩子需要真实的花钱练习：想买玩具？零花钱就这些，买这个就不能买那个——取舍/预算/存钱都从这学起），不给零花钱的孩子（没练过花钱）长大更容易乱花钱（突然有了自主权，报复性消费）——零花钱是『教育工具』不是『奖励/施舍』；②孩子乱花钱怎么办——先理解：乱花（看见什么都想买/钱到手就花光）是正常的（孩子没有金钱概念，需要教不是骂）——应对：约定规则（每周零花钱固定数额，花完没有（不追加，让他体验『没钱』的后果））+ 引导记账（买了什么记下来，月底回顾）+ 讨论取舍（想买贵的？自己存几周——延迟满足训练）——『乱花』是过程，教出『会花』才是目的；③零花钱是惯孩子吗——不是：惯是『无条件满足』（要什么给什么，零花钱是溺爱的形式），零花钱教育是『有规则地给』（固定数额/约定用途/花完自理）——区别在『规则』：无规则地给=惯，有规则地给=教育，而且零花钱还教『钱的来源』（不是天上掉的：和家务挂钩（做家务赚零花钱）或固定发放（零花钱是权利，不是劳动的报酬，看家庭观念））；④不给孩子钱孩子偷拿怎么办——偷拿是信号不是品德问题：孩子偷拿（想买东西没钱/不敢要）说明：零花钱机制缺失（没给钱→孩子只能用偷的方式满足）+沟通问题（不敢跟父母说）——应对：不贴『小偷』标签（打骂会让孩子更不敢说）、给零花钱（解决『没钱』的根源）、建立信任（『想要什么跟我说，我们商量，别偷偷拿』）——偷拿是教育的失败，不是孩子的坏（孩子没有财商，财商靠父母教）。怎么给才合理：①年龄分级——6岁起给（每周几块，学认识钱/存钱）、小学中高年级（每周10-50，学预算/记账）、初中（每月给，按月管理，学规划）、高中（更多+自己支配，学独立）——金额参考同龄人/家庭收入（别给太少（学不到）也别给太多（失去教育意义））；②规则先行——固定时间发（每周/每月固定）、用途约定（零食/玩具自己买，大件（手机/电脑）家长出）、花完不补（让他体验后果，这是最好的老师）；③配套教育——记账本（买了什么/花了多少）、三罐法（花/存/捐：学花钱也学存钱和分享）、讨论消费观（广告是让你买的/想要和需要的区别）——零花钱+讨论=财商课；④心态——孩子的乱花是学费（现在乱花几块钱学到的，比长大乱花几万学到的便宜多了），允许犯错（孩子花光钱后悔的体验，比你说一百遍『省着花』有用）。核心：零花钱是孩子的人生第一堂理财课——给钱+立规则+教方法，孩子学会的是『管理钱』不是『被钱管理』，这比省下的那点零花钱值钱得多",
    "注意机制": "注意机制是认知资源的选择性分配——选择性注意（聚焦）/分散注意（多任务）/持续注意；对应CSPMN只匹配激活条件空间",'''
    assert anchor_d in src, "daily anchor missing"
    src = src.replace(anchor_d, new_d, 1)
    open(path, "w", encoding="utf-8").write(src)
    print("patched")

